UPDATE  csh_write_off  SET  reversed_flag = "W" , reversed_write_off_id = #{writeOffId} ,reversed_date = #{reversedDate},OBJECT_VERSION_NUMBER = nvl(OBJECT_VERSION_NUMBER,0) + 1
WHERE
write_off_id = #{wId}

mapper.select:
SELECT con.contract_number AS contractNumber, con.contract_id AS contractId, con.bp_id AS bpId, con.bp_name AS bpName, con.times AS times, con.due_date AS dueDate, con.due_amount AS dueAmount, con.interest AS interest, con.cf_item AS cfItem, con.cf_type AS cfType, con.description AS description, con.transaction_amount AS transactionAmount, con.cashflow_id AS cashflowId, con.company_id AS companyId, con.deduction_doc_category AS deductionDocCategory FROM ( ( SELECT cc.contract_number , cc.contract_id , bp.bp_id , bp.bp_name , csh.times , csh.due_date , csh.due_amount , csh.interest , csh.cf_item , csh.cf_type , hci.description , (csh.due_amount - nvl(csh.received_amount,0)) transaction_amount, csh.cashflow_id, cc.company_id, 'CON_CONTRACT' deduction_doc_category FROM con_contract_cashflow csh, hls_bp_master bp, hls_cashflow_item hci, con_contract cc WHERE csh.cf_item in(1,9) AND hci.cf_direction = 'INFLOW' AND hci.cf_item = csh.cf_item AND csh.write_off_flag IN ('NOT', 'PARTIAL') AND bp.bp_id = cc.tenant_id AND cc.data_class='NORMAL' AND cc.contract_id=csh.contract_id) UNION ( SELECT fc.contract_number , fc.contract_id , bp.bp_id , bp.bp_name , fqc.times , fqc.due_date , fqc.due_amount , fqc.interest , fqc.cf_item , fqc.cf_type , hci.description , (nvl(fqc.due_amount,0) - nvl(fqc.received_amount,0)) transaction_amount, fqc.quotation_cashflow_id cashflow_id, fc.company_id, 'FCT_CONTRACT' deduction_doc_category FROM fct_quotation_cashflow fqc, hls_bp_master bp, hls_cashflow_item hci, fct_contract fc, fct_project_bp fcb WHERE fqc.cf_item in (54,55,45) AND hci.cf_direction = 'INFLOW' AND hci.cf_item = fqc.cf_item AND fqc.write_off_flag IN ('NOT', 'PARTIAL') AND fc.data_class='NORMAL' AND fcb.credit_grantor_party='Y' AND fc.contract_id=fqc.contract_id AND fc.project_id=fcb.project_id AND bp.bp_id = fcb.bp_id )) con WHERE 1=1 AND con.cashflow_id not in ( select cdd.cashflow_id from csh_deposit_deduction cdd, csh_deposit_deduction_hd cddh where cddh.deposit_status in('NEW', 'APPROVING', 'REJECTED', 'APPROVED_RETURN') and cdd.deposit_deduction_hd_id=cddh.deposit_deduction_hd_id and cdd.deduction_doc_category=con.deduction_doc_category ) AND con.cashflow_id not in ( select cwom.cashflow_id from csh_write_off_match cwom where cwom.write_flag in('R', 'N') and cwom.cashflow_id is not null and cwom.write_off_doc_category=con.deduction_doc_category )
AND con.times = #{times}
AND con.contract_id = #{contractId}
AND con.deduction_doc_category = #{deductionDocCategory}
AND con.contract_number = #{contractNumber}
ORDER BY contract_number,times ASC
ORDER BY con.due_date DESC,con.times DESC

SELECT cc.contract_number AS contractNumber, cc.contract_id AS contractId, bp.bp_name AS bpName, csh.times AS times, csh.due_date AS dueDate, csh.due_amount AS dueAmount, csh.cf_item AS cfItem, csh.cf_type AS cfType, hci.description AS description, ( csh.due_amount - csh.received_amount ) AS transactionAmount, csh.cashflow_id AS cashflowId, csh.interest FROM con_contract_cashflow csh, hls_bp_master bp, hls_cashflow_item hci, con_contract cc WHERE hci.cf_direction = 'INFLOW' AND hci.cf_item = csh.cf_item AND csh.write_off_flag in ('FULL') AND bp.bp_id = cc.tenant_id and csh.cf_item=1 AND cc.contract_id = csh.contract_id
AND cct.tenant_bp_id = #{bpId}
AND csh.times = #{times}
AND cc.contract_number = #{contractNumber}
ORDER BY contract_number,times ASC

SELECT ct.transaction_id, bp.bp_id, bp.bp_code, bp.bp_name, nvl(ct.transaction_amount,0) as transaction_amount, nvl(ct.transaction_amount,0) - nvl(ct.write_off_amount, 0) AS left_amount, ct.bank_slip_num, ct.transaction_date, case (select count(1) from csh_transaction ct where ct.source_doc_id = ct.transaction_id and ct.transaction_type = 'REFUND') when 0 THEN -1 ELSE 1 END refund_flag FROM csh_transaction ct, hls_bp_master bp WHERE ct.business_type = 'DEPOSIT' AND ct.transaction_type = 'DEPOSIT_POOL' AND bp.bp_id = ct.bp_id AND ct.company_id = #{companyId}
AND (bp.bp_name LIKE concat(concat('%',#{bp_name}),'%') OR bp.bp_code LIKE concat(concat('%',#{bp_name}),'%'))
ORDER BY ct.transaction_date DESC

SELECT ct.transaction_id, cwo.write_off_id, cwo.write_off_date, ct.transaction_num, bp.bp_name, ct.bank_slip_num, cwo.csh_write_off_amount, (select fc.currency_name from fnd_currency fc where fc.currency_code=ct.currency_code) currency_name, ct.currency_code, ( select sc.code_value_name from
sc where sc.CODE = 'CSH.PAYMENT_METHOD' and sc.code_value=ct.payment_method ) payment FROM csh_write_off cwo, csh_transaction ct, hls_bp_master bp WHERE cwo.csh_transaction_id = ct.transaction_id AND cwo.reversed_flag = 'N' AND bp.bp_id = ct.bp_id AND ct.reversed_flag = 'N' and cwo.write_off_type='RECEIPT_DEPOSIT_POOL' AND ct.company_id = #{companyId}
AND cwo.subsequent_csh_trx_id = #{transaction_id}
